import{_ as a,o as t,c as e,ae as n}from"./chunks/framework.Dzr56EFm.js";const c=JSON.parse('{"title":"设计趋势 - 2026-07-10","description":"","frontmatter":{"date":"2026-07-10T00:00:00.000Z","category":"UX Trend"},"headers":[],"relativePath":"daily/2026-07-10-uxtrend.md","filePath":"daily/2026-07-10-uxtrend.md"}'),o={name:"daily/2026-07-10-uxtrend.md"};function s(i,r,g,p,h,l){return t(),e("div",null,[...r[0]||(r[0]=[n('<h1 id="设计趋势-2026-07-10" tabindex="-1">设计趋势 - 2026-07-10 <a class="header-anchor" href="#设计趋势-2026-07-10" aria-label="Permalink to &quot;设计趋势 - 2026-07-10&quot;">​</a></h1><blockquote><p>AI交互方式、Prompt UX、Agent UX、Workflow</p></blockquote><h2 id="今日概览" tabindex="-1">今日概览 <a class="header-anchor" href="#今日概览" aria-label="Permalink to &quot;今日概览&quot;">​</a></h2><p>今日设计趋势聚焦于AI与用户体验的融合。主要动态包括：1) 面向代理的用户体验设计，探讨新型数字设备体验原则；2) AI工具如Cursor和Manus推动用户体验革命；3) 代理型UX设计强调人机信任；4) 定义AI交互范式，提供设计原则；5) AI优化设计工作流程，提升速度和效率。最值得关注的是AI工具在设计流程中的应用，以及AI交互范式的创新。</p><hr><h3 id="_1-面向代理的用户体验设计" tabindex="-1">1. 面向代理的用户体验设计 <a class="header-anchor" href="#_1-面向代理的用户体验设计" aria-label="Permalink to &quot;1. 面向代理的用户体验设计&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/microsoft-design/ux-design-for-agents-11336728b445" target="_blank" rel="noreferrer">UX design for agents</a></p><p><strong>一句话摘要</strong>: 探讨设计新型数字设备用户体验的原则</p><p><strong>能解决什么问题</strong>: 如何将人工智能代理系统融入日常生活并优化用户体验</p><p><strong>产品应用</strong>: 适用于产品设计，以人为中心，加速开发并强调人工智能的价值</p><p><strong>示例场景</strong>: 智能助手协助用户进行日常任务规划和情绪管理</p><hr><h3 id="_2-光标、氛围编码和手稿-ai所需的用户体验革命" tabindex="-1">2. 光标、氛围编码和手稿：AI所需的用户体验革命 <a class="header-anchor" href="#_2-光标、氛围编码和手稿-ai所需的用户体验革命" aria-label="Permalink to &quot;2. 光标、氛围编码和手稿：AI所需的用户体验革命&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/cursor-vibe-coding-and-manus-the-ux-revolution-that-ai-needs-3d3a0f8ccdfa" target="_blank" rel="noreferrer">Cursor, “vibe coding,” and Manus: the UX revolution that AI needs | by Amy Chivavibul | UX Collective</a></p><p><strong>一句话摘要</strong>: Cursor和Manus等工具通过直接嵌入AI到工作流程中，推动了用户体验的革命。</p><p><strong>能解决什么问题</strong>: 提高开发者与AI协作的效率，减少操作复杂性。</p><p><strong>产品应用</strong>: 适用于软件开发领域，作为集成开发环境提升代码编写和调试效率。</p><p><strong>示例场景</strong>: 开发者通过Cursor直接向AI请求代码优化。</p><hr><h3 id="_3-为什么代理型ux将改变你对设计的了解" tabindex="-1">3. 为什么代理型UX将改变你对设计的了解 <a class="header-anchor" href="#_3-为什么代理型ux将改变你对设计的了解" aria-label="Permalink to &quot;3. 为什么代理型UX将改变你对设计的了解&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/generative-ai-revolution-ai-native-transformation/why-agentic-ux-will-change-everything-you-know-about-design-0394486f5add" target="_blank" rel="noreferrer">Why Agentic UX Will Change Everything You Know About Design</a></p><p><strong>一句话摘要</strong>: 代理型UX设计关注于建立人机之间的信任。</p><p><strong>能解决什么问题</strong>: 如何让用户信任并有效利用AI代理系统。</p><p><strong>产品应用</strong>: 适用于需要人机协作的智能系统，如企业自动化流程。</p><p><strong>示例场景</strong>: AI代理提示用户审查并提交季度预算。</p><hr><h3 id="_4-人工智能设计交互范式-类别、模式与设计考量" tabindex="-1">4. 人工智能设计交互范式：类别、模式与设计考量 <a class="header-anchor" href="#_4-人工智能设计交互范式-类别、模式与设计考量" aria-label="Permalink to &quot;4. 人工智能设计交互范式：类别、模式与设计考量&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://hanjing.medium.com/ai-interaction-paradigms-7caace4593ba" target="_blank" rel="noreferrer">AI Design Interaction Paradigms. Categories, Patterns, and Design… | by hanjing | Medium</a></p><p><strong>一句话摘要</strong>: 定义AI交互范式，提供设计原则以创造可用、可信、直观的AI体验。</p><p><strong>能解决什么问题</strong>: 解决用户与AI交互时的意图理解、自主性、可见性和控制问题。</p><p><strong>产品应用</strong>: 适用于产品设计和设计团队，指导如何设计不同AI模式的行为。</p><p><strong>示例场景</strong>: 使用Agentic AI范式，创建安全空间让用户实验对话。</p><hr><h3 id="_5-ai如何改变我的设计工作流程" tabindex="-1">5. AI如何改变我的设计工作流程 <a class="header-anchor" href="#_5-ai如何改变我的设计工作流程" aria-label="Permalink to &quot;5. AI如何改变我的设计工作流程&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@kazdenc/how-my-design-workflow-is-changing-with-ai-bc80e7fa3323" target="_blank" rel="noreferrer">How my design workflow is changing with AI</a></p><p><strong>一句话摘要</strong>: AI让设计流程更快速、协作，减少猜测，增加测试。</p><p><strong>能解决什么问题</strong>: 缩短从想法到执行的距离，降低成本，减少死胡同。</p><p><strong>产品应用</strong>: 适用于产品设计，通过快速原型迭代提升效率。</p><p><strong>示例场景</strong>: 使用Figma和Cursor进行交互式原型设计。</p><hr><h3 id="_6-ai与设计-人工智能如何协助设计师以及设计师如何创造ai友好型产品" tabindex="-1">6. AI与设计：人工智能如何协助设计师以及设计师如何创造AI友好型产品 <a class="header-anchor" href="#_6-ai与设计-人工智能如何协助设计师以及设计师如何创造ai友好型产品" aria-label="Permalink to &quot;6. AI与设计：人工智能如何协助设计师以及设计师如何创造AI友好型产品&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@gwrx2005/ai-and-design-how-artificial-intelligence-assists-designers-and-how-designers-create-ai-friendly-df97320884ae" target="_blank" rel="noreferrer">AI and Design: How Artificial Intelligence Assists Designers and How Designers Create AI‑Friendly…</a></p><p><strong>一句话摘要</strong>: AI技术通过对话界面增强设计师工作流程，同时使AI系统更易用和可信。</p><p><strong>能解决什么问题</strong>: 解决设计师如何有效利用AI工具提升设计效率和用户体验的问题。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，如设计聊天机器人和语音助手，提升交互效率。</p><p><strong>示例场景</strong>: 设计一个AI驱动的聊天机器人，帮助用户通过自然语言完成复杂任务。</p><hr><h3 id="_7-ai代理工作流设计模式概览" tabindex="-1">7. AI代理工作流设计模式概览 <a class="header-anchor" href="#_7-ai代理工作流设计模式概览" aria-label="Permalink to &quot;7. AI代理工作流设计模式概览&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/binome/ai-agent-workflow-design-patterns-an-overview-cf9e1f609696" target="_blank" rel="noreferrer">AI Agent Workflow Design Patterns — An Overview | by Craig Li, Ph.D | Binome | Medium</a></p><p><strong>一句话摘要</strong>: 探讨AI代理工作流设计模式，强调工作流作为任务协调器的作用。</p><p><strong>能解决什么问题</strong>: 如何设计AI代理以模拟人类推理、规划和执行任务。</p><p><strong>产品应用</strong>: 可应用于开发智能代理，通过工作流模式灵活处理不同问题。</p><p><strong>示例场景</strong>: 智能助手根据用户需求规划并执行任务。</p><hr><h3 id="_8-为人工智能设计-设计人工智能特性的交互" tabindex="-1">8. 为人工智能设计：设计人工智能特性的交互 <a class="header-anchor" href="#_8-为人工智能设计-设计人工智能特性的交互" aria-label="Permalink to &quot;8. 为人工智能设计：设计人工智能特性的交互&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/@ux.haowu/design-for-ai-2-designing-interactions-for-ai-features-d776d6388bdd" target="_blank" rel="noreferrer">Design for AI 2: Designing Interactions for AI Features</a></p><p><strong>一句话摘要</strong>: AI辅助用户交互，预测意图并实时提供补全。</p><p><strong>能解决什么问题</strong>: 提高工作效率，减少输入错误，保持用户专注。</p><p><strong>产品应用</strong>: 适用于需要快速输入和减少错误的场景，如邮件客户端和代码编辑器。</p><p><strong>示例场景</strong>: Figma中自动补全地址，Notion中“问AI”字段即时显示命令匹配。</p><hr><h3 id="_9-主动式ai工作流设计模式、实例及2025年展望" tabindex="-1">9. 主动式AI工作流设计模式、实例及2025年展望 <a class="header-anchor" href="#_9-主动式ai工作流设计模式、实例及2025年展望" aria-label="Permalink to &quot;9. 主动式AI工作流设计模式、实例及2025年展望&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://medium.com/codex/agentic-ai-workflows-design-patterns-examples-and-what-to-watch-in-2025-a3602b19b7e8" target="_blank" rel="noreferrer">Agentic AI Workflows Design Patterns, Examples, and what to watch in 2025</a></p><p><strong>一句话摘要</strong>: 主动式AI工作流结合AI和ML自动化执行任务。</p><p><strong>能解决什么问题</strong>: 解决重复性工作，释放人力专注于高价值任务。</p><p><strong>产品应用</strong>: 适用于需要自动化和智能决策的企业级应用。</p><p><strong>示例场景</strong>: 智能物流系统自动优化配送路线。</p><hr><h3 id="_10-ai在ui中的位置-映射新兴ai-ui模式" tabindex="-1">10. AI在UI中的位置：映射新兴AI UI模式 <a class="header-anchor" href="#_10-ai在ui中的位置-映射新兴ai-ui模式" aria-label="Permalink to &quot;10. AI在UI中的位置：映射新兴AI UI模式&quot;">​</a></h3><p><strong>原文标题</strong>: <a href="https://uxdesign.cc/where-should-ai-sit-in-your-ui-1710a258390e" target="_blank" rel="noreferrer">Where should AI sit in your UI?. Mapping emerging AI UI patterns and how… | by Sharang Sharma | UX Collective</a></p><p><strong>一句话摘要</strong>: 分析AI UI模式，指导如何将AI融入用户界面。</p><p><strong>能解决什么问题</strong>: 如何将AI技术合理地融入用户界面以提升用户体验。</p><p><strong>产品应用</strong>: 可以应用到实际产品中，通过自然语言交互和上下文触发提供辅助。</p><p><strong>示例场景</strong>: 在设计软件中，用户通过AI助手生成文本和布局。</p><hr>',75)])])}const u=a(o,[["render",s]]);export{c as __pageData,u as default};
